import { describe, it, expect } from 'vitest'
import { createPanier, addItem } from '../../src/panier.js'

const pomme = { id: 'a', nom: 'Pomme', prix: 2 }

describe('step 1.2 — ajout', () => {
  it('ajoute une ligne', () => {
    const p = addItem(createPanier(), pomme, 3)
    expect(p.lignes).toHaveLength(1)
    expect(p.lignes[0].qty).toBe(3)
    expect(p.lignes[0].item.id).toBe('a')
  })

  it('regroupe le même article', () => {
    let p = addItem(createPanier(), pomme, 1)
    p = addItem(p, pomme, 2)
    expect(p.lignes).toHaveLength(1)
    expect(p.lignes[0].qty).toBe(3)
  })

  it('ne mute pas l entrée', () => {
    const vide = createPanier()
    addItem(vide, pomme, 1)
    expect(vide.lignes).toHaveLength(0)
  })
})

