import { describe, it, expect } from 'vitest'
import { createPanier, addItem, total, applyPromo } from '../../src/panier.js'

const plein = () => addItem(createPanier(), { id: 'a', nom: 'X', prix: 10 }, 2)

describe('step 1.5 — promo', () => {
  it('stocke un code valide', () => {
    expect(applyPromo(plein(), 'PROMO10').promo).toBe('PROMO10')
  })

  it('ignore un code inconnu', () => {
    expect(applyPromo(plein(), 'NIMPORTEQUOI').promo).toBeNull()
  })

  it('applique un pourcentage', () => {
    expect(total(applyPromo(plein(), 'PROMO10'))).toBe(18)
  })

  it('applique un montant fixe', () => {
    expect(total(applyPromo(plein(), 'MOINS5'))).toBe(15)
  })

  it('ne descend jamais sous zéro', () => {
    const petit = addItem(createPanier(), { id: 'b', nom: 'Y', prix: 1 }, 1)
    expect(total(applyPromo(petit, 'MOINS5'))).toBe(0)
  })
})

solution.src/panier.js:
export function createPanier() {
  return { lignes: [], promo: null }
}

export const PROMOS = {
  PROMO10: { type: 'percent', valeur: 10 },
  MOINS5: { type: 'fixed', valeur: 5 },
}

export function addItem(panier, item, qty = 1) {
  const existe = panier.lignes.some((l) => l.item.id === item.id)
  const lignes = existe
    ? panier.lignes.map((l) =>
        l.item.id === item.id ? { ...l, qty: l.qty + qty } : l
      )
    : [...panier.lignes, { item, qty }]
  return { ...panier, lignes }
}

export function applyPromo(panier, code) {
  return { ...panier, promo: PROMOS[code] ? code : null }
}

export function total(panier) {
  const brut = panier.lignes.reduce((acc, l) => acc + l.item.prix * l.qty, 0)
  const promo = panier.promo ? PROMOS[panier.promo] : null
  let net = brut
  if (promo?.type === 'percent') net = brut * (1 - promo.valeur / 100)
  if (promo?.type === 'fixed') net = brut - promo.valeur
  return Math.round(Math.max(0, net) * 100) / 100
}
